window.ScripturaLexicons.BDAG_PART_0315 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0315-01\" data-source=\"BDAG\" data-search=\"Ῥεβέκκα, ας, ἡ nome próprio feminino Rebeca BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ῥεβέκκα, ας, ἡ</td><td>nome próprio feminino</td><td>Rebeca</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0315-02\" data-source=\"BDAG\" data-search=\"ῥέδη, ης, ἡ substantivo feminino carruagem de viagem BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ῥέδη, ης, ἡ</td><td>substantivo feminino</td><td>carruagem de viagem</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0315-03\" data-source=\"BDAG\" data-search=\"Ῥεμφάν, Ῥεφάν remissão ver Ῥαιφάν BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ῥεμφάν, Ῥεφάν</td><td>remissão</td><td>ver Ῥαιφάν</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0315-04\" data-source=\"BDAG\" data-search=\"Ῥέος, ου, ὁ nome próprio masculino Reu, de sobrenome Agátopo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ῥέος, ου, ὁ</td><td>nome próprio masculino</td><td>Reu, de sobrenome Agátopo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0315-05\" data-source=\"BDAG\" data-search=\"ῥέραμμαι forma verbal remissiva ver ῥαίνω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ῥέραμμαι</td><td>forma verbal remissiva</td><td>ver ῥαίνω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0315-06\" data-source=\"BDAG\" data-search=\"ῥεριμμένος forma verbal remissiva ver ῥίπτω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ῥεριμμένος</td><td>forma verbal remissiva</td><td>ver ῥίπτω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0315-07\" data-source=\"BDAG\" data-search=\"ῥέω verbo fluir; transbordar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ῥέω</td><td>verbo</td><td>fluir; transbordar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0315-08\" data-source=\"BDAG\" data-search=\"Ῥήγιον, ου, τό nome próprio neutro Régio BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ῥήγιον, ου, τό</td><td>nome próprio neutro</td><td>Régio</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0315-09\" data-source=\"BDAG\" data-search=\"ῥῆγμα, ατος, τό substantivo neutro ruína, desmoronamento BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ῥῆγμα, ατος, τό</td><td>substantivo neutro</td><td>ruína, desmoronamento</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0315-10\" data-source=\"BDAG\" data-search=\"ῥήγνυμι verbo rasgar, romper, rebentar; irromper BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ῥήγνυμι</td><td>verbo</td><td>rasgar, romper, rebentar; irromper</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0315-11\" data-source=\"BDAG\" data-search=\"ῥηθείς forma verbal remissiva ver εἶπον BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ῥηθείς</td><td>forma verbal remissiva</td><td>ver εἶπον</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0315-12\" data-source=\"BDAG\" data-search=\"ῥῆμα, ατος, τό substantivo neutro palavra, declaração; coisa, assunto, acontecimento BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ῥῆμα, ατος, τό</td><td>substantivo neutro</td><td>palavra, declaração; coisa, assunto, acontecimento</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0315-13\" data-source=\"BDAG\" data-search=\"Ῥησά, ὁ nome próprio masculino indeclinável Resá BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ῥησά, ὁ</td><td>nome próprio masculino indeclinável</td><td>Resá</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0315-14\" data-source=\"BDAG\" data-search=\"ῥῆσις, εως, ἡ substantivo feminino palavra, expressão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ῥῆσις, εως, ἡ</td><td>substantivo feminino</td><td>palavra, expressão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0315-15\" data-source=\"BDAG\" data-search=\"ῥήσσω verbo romper; derrubar, lançar ao chão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ῥήσσω</td><td>verbo</td><td>romper; derrubar, lançar ao chão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0315-16\" data-source=\"BDAG\" data-search=\"ῥήτωρ, ορος, ὁ substantivo masculino orador; advogado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ῥήτωρ, ορος, ὁ</td><td>substantivo masculino</td><td>orador; advogado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0315-17\" data-source=\"BDAG\" data-search=\"ῥητῶς advérbio expressamente, explicitamente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ῥητῶς</td><td>advérbio</td><td>expressamente, explicitamente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0315-18\" data-source=\"BDAG\" data-search=\"ῥίζα, ης, ἡ substantivo feminino raiz; rebento, descendente; sopé BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ῥίζα, ης, ἡ</td><td>substantivo feminino</td><td>raiz; rebento, descendente; sopé</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0315-19\" data-source=\"BDAG\" data-search=\"ῥιζόω verbo fazer enraizar; firmar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ῥιζόω</td><td>verbo</td><td>fazer enraizar; firmar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0315-20\" data-source=\"BDAG\" data-search=\"ῥιπή, ῆς, ἡ substantivo feminino movimento rápido; piscar de olhos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ῥιπή, ῆς, ἡ</td><td>substantivo feminino</td><td>movimento rápido; piscar de olhos</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0315-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ῥεβέκκα, ας, ἡ</h1><div class=\"entry-meta\"><span>nome próprio feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Ῥεβέκκα</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (<span class=\"hebrew\">רִבְקָה</span>; declinado na LXX, em Philo e Joseph.) Rebeca, esposa de Isaque <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:10</a>; B 13:2 (Gen 25:21), 3.—BHHW III 1558.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0315-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥέδη, ης, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ῥέδη</span>, <span class=\"greek\">ης</span>, <span class=\"greek\">ἡ</span> (segundo Quintilian 1, 5, 57, originalmente uma palavra céltica [v. também Caesar, Bell. Gall. 1, 51; 6, 30]. Entrou na lit. grega por intermédio de autores latinos [na forma ‘reda’ ou ‘raeda’ em Cicero; Horace, Sat. 1, 5, 86; 2, 6, 42; Suetonius, Jul. 57 al.]. V. a respeito dela, bem como da grafia <span class=\"greek\">ῥαίδη</span>, B-D-F §5, 1d; 41, 1; Mlt-H. 81; 155; Hahn 263, 5 [lit.]) carruagem de viagem de quatro rodas, carruagem <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.13\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 18:13</a> (variante de grafia <span class=\"greek\">ῥαίδη</span>).—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0315-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ῥεμφάν, Ῥεφάν</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Ῥεμφάν</span>, <span class=\"greek\">Ῥεφάν</span> v. <span class=\"greek\">Ῥαιφάν</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0315-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ῥέος, ου, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Ῥέος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> Reu, de sobrenome Agátopo (v. <span class=\"greek\">Ἀγαθόπους</span>) IPhld 11:1 (v. Hdb. sobre a passagem); ISm 10:1.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0315-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥέραμμαι</h1><div class=\"entry-meta\"><span>forma verbal remissiva</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ῥέραμμαι</span> v. <span class=\"greek\">ῥαίνω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0315-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥεριμμένος</h1><div class=\"entry-meta\"><span>forma verbal remissiva</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ῥεριμμένος</span> v. <span class=\"greek\">ῥίπτω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0315-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ῥέω</span> (Hom.+; inscr., pap., LXX; TestJob 13:1; JosAs 29:1; Apc-Mos; SibOr 3, 54; Philo; Jos., Bell. 6, 105 <span class=\"greek\">μνήμη</span> <span class=\"greek\">ῥέουσα</span> <span class=\"greek\">δι</span>’ <span class=\"greek\">αἰῶνος</span>; Just.; Mel., HE 4, 26, 9) fut. <span class=\"greek\">ῥεύσω</span> (B-D-F §77; Rob. 355); aor. imper. 3ª pess. pl. <span class=\"greek\">ῥευσάτωσαν</span> SSol 4:16; part. gen. sing. <span class=\"greek\">ῥεύσαντος</span> (Just., D. 67, 2). Pass.: fut. 3ª pess. sing. <span class=\"greek\">ῥυήσεται</span> LXX; aor. 3ª pess. sing. <span class=\"greek\">ἐρρύη</span> LXX, inf. <span class=\"greek\">ῥυῆναι</span> (Mel.) fluir, tratando-se de líquido, em nossa lit. somente em sentido translato</p><p class=\"entry-text\">ⓐ como símbolo de bênção transcendente, fluir <span class=\"greek\">ποταμοὶ</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">κοιλίας</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">ῥεύσουσιν</span> <span class=\"greek\">ὕδατος</span> <span class=\"greek\">ζῶντος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.38\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:38</a> (Hdb. ad loc., e v. <span class=\"greek\">κοιλία</span> 3).</p><p class=\"entry-text\">ⓑ fig. no sentido de ‘ter mais do que o suficiente de’: fluir ou transbordar de <span class=\"greek\">τὶ</span> algo <span class=\"greek\">γῆ</span> <span class=\"greek\">ῥέουσα</span> <span class=\"greek\">γάλα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μέλι</span> uma terra que mana leite e mel (LXX) B 6:8, 10, 13 (para um tratamento mais detalhado desta passagem, v. Windisch, Hdb. sobre B 6:8.—V. também <span class=\"greek\">γάλα</span> a).—B. 677. DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0315-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ῥήγιον, ου, τό</h1><div class=\"entry-meta\"><span>nome próprio neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Ῥήγιον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (Aeschyl., Hdt. et al.; inscr.; Philo, Aet. M. 139; Jos., Ant. 19, 205) Régio, cidade e promontório no Brútio, na ‘ponta do pé’ da Itália, em frente à cidade siciliana de Messina <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:13</a>.—Pauly-W. I 487–502; Kl. Pauly IV 1367; BHHW III 1572; PECS 753f.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0315-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥῆγμα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ῥῆγμα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (<span class=\"greek\">ῥήγνυμι</span>; desde Archippus Com. [V/IV a.C.], Fgm. 38; Hippocr.; pap., LXX; Jos., Bell. 6, 337) o acontecimento da redução a um estado de ruína, destruição, ruína, desmoronamento, lit. ‘ruptura’ <span class=\"greek\">τῆς</span> <span class=\"greek\">οἰκίας</span> (este sentido não se encontra alhures; mas o pl. com referência a edifícios: Polyb. 13, 6, 8; PSI 456, 11 <span class=\"greek\">τοῦ</span> <span class=\"greek\">πύργου</span> <span class=\"greek\">ῥήγματα</span>; Am 6:11 v.l. <span class=\"greek\">πατάξει</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">οἶκον</span> <span class=\"greek\">ῥήγμασιν</span>.—PLond I, 131 recto, 45; 60 pp. 171f [78/79 d.C.] emprega a palavra a respeito de uma ruptura em um dique no Nilo, isto é, de dano causado pela água) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.49\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:49</a>.—DELG s.v. <span class=\"greek\">ῥήγνυμι</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0315-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥήγνυμι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ῥήγνυμι</span> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:17</a> e sua forma variante <span class=\"greek\">ῥήσσω</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:17</a> D; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:6</a> D) fut. <span class=\"greek\">ῥήξω</span>; 1 aor. <span class=\"greek\">ἔρ</span>(<span class=\"greek\">ρ</span>)<span class=\"greek\">ηξα</span>, imper. <span class=\"greek\">ῥῆξον</span>; perf. 3ª pess. pl. <span class=\"greek\">ἐρρώγασιν</span> Josh 9:13, part. <span class=\"greek\">ἐρρηγώς</span> Job 32:19. Pass.: 2 fut. <span class=\"greek\">ῥαγήσομαι</span>; 2 aor. <span class=\"greek\">ἐρράγην</span> LXX; inf. <span class=\"greek\">ῥαγῆναι</span> AcPl Ha 3, 11 (Hom.+; LXX; TestSol; TestJob 28:3; TestJud 2:6; Mel., P. 91, 682; Ath., 18, 3)</p><p class=\"entry-text\">① fazer com que algo se separe ou fique em pedaços por meio de uma força interna ou externa, despedaçar, romper, rebentar <span class=\"greek\">τινά</span> ou <span class=\"greek\">τὶ</span> alguém ou algo (Jos., Ant. 5, 310) a respeito do vinho <span class=\"greek\">τοὺς</span> <span class=\"greek\">ἀσκούς</span> rebentar os odres (Alex. Aphr., An. Mant. 124, 20 Br.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:22</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:17</a> D; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.37\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:37</a>. Pass. ser rasgado, rebentar (Diod S 3, 34, 2; TestJud 2:6; ViHab 12; PGM 4, 361; 2674; 13, 264) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:17</a>. <span class=\"greek\">ὥστε</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">δίκτυα</span> <span class=\"greek\">ῥήσσεσθαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:6</a> D. <span class=\"greek\">ῥαγῆναι</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">δεσμά</span> AcPl Ha 3, 11. A respeito de animais ferozes, despedaçar com os dentes <span class=\"greek\">μήποτε</span> <span class=\"greek\">ῥήξωσιν</span> <span class=\"greek\">ὑμᾶς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:6</a> (Aesop, Fab. 408a H., a respeito de um porco: <span class=\"greek\">τοῖς</span> <span class=\"greek\">ὀδοῦσιν</span> <span class=\"greek\">ἀναῤῥήξειν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">κύνα</span>; cf. a versão alternativa: 408b H. <span class=\"greek\">ἀνατεμεῖν</span> ‘cortar em pedaços’//250 III H-H. <span class=\"greek\">ἀνατεμεῖ</span>).</p><p class=\"entry-text\">② efetuar uma ação ou intensificá-la, livrando-se inicialmente da contenção, romper, soltar, dar livre curso, irromper em (Hdt. 2, 2, 3 e Aelian, Fgm. 41 p. 203, 2 <span class=\"greek\">φωνήν</span>; Plut., Pericl. 172 [36, 7] <span class=\"greek\">κλαυθμόν</span>; LXX; Philo, Conf. Lingu. 194. Cf. também Ps.-Oppian, Cyneg. 1, 226 <span class=\"greek\">ῥῆξεν</span> <span class=\"greek\">ποτὲ</span> <span class=\"greek\">δεσμὰ</span> <span class=\"greek\">σιωπῆς</span>) <span class=\"greek\">ῥῆξον</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">βόησον</span> irrompe e clama em alta voz (Is 54:1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.27\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:27</a>; 2 Cl 2:1.—Pass. irromper (PPetr II, 23, 1, 12 [III a.C.] <span class=\"greek\">ὕδωρ</span> <span class=\"greek\">ἐρράγη</span>; SibOr 4, 53) a respeito da luz B 3:4 (Is 58:8).—V. também <span class=\"greek\">ῥήσσω</span>.—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0315-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥηθείς</h1><div class=\"entry-meta\"><span>forma verbal remissiva</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ῥηθείς</span> v. <span class=\"greek\">εἶπον</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0315-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥῆμα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ῥῆμα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (Pind.; Pla., Leg. 840c [com <span class=\"greek\">μῦθο</span>], provavelmente a respeito de máximas edificantes; Hdt.+)</p><p class=\"entry-text\">① aquilo que é dito, palavra, dito, expressão ou declaração de qualquer espécie <span class=\"greek\">τὰ</span> <span class=\"greek\">ῥήματα</span> as palavras (oposto a <span class=\"greek\">τὰ</span> <span class=\"greek\">ἔργα</span>) 2 Cl 13:3; Hs 9, 21, 2; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.38\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:38</a>. <span class=\"greek\">πᾶν</span> <span class=\"greek\">ῥῆμα</span> toda palavra B 11:8. <span class=\"greek\">πᾶν</span> <span class=\"greek\">ῥῆμα</span> <span class=\"greek\">ἀργόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:36</a>. <span class=\"greek\">πᾶν</span> <span class=\"greek\">ῥ</span>. <span class=\"greek\">πονηρόν</span> Hs 5, 3, 6; <span class=\"greek\">οὐδὲ</span> <span class=\"greek\">ἓν</span> <span class=\"greek\">ῥ</span>. nem sequer uma palavra <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:14</a>; cf. <span class=\"greek\">ῥῆμα</span> <span class=\"greek\">ἕν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:25</a>.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:17</a>, 50; 20:26; 1 Cl 27:7 (Ps 18:3). <span class=\"greek\">φωνὴ</span> <span class=\"greek\">ῥημάτων</span> o som das palavras, uma voz cujas palavras <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.19\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:19</a>; <span class=\"greek\">αἰσχρὸν</span> <span class=\"greek\">ῥ</span>. Hv 1, 1, 7. <span class=\"greek\">ὡσεὶ</span> <span class=\"greek\">λῆρος</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ῥ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:11</a>. <span class=\"greek\">ἄρρητα</span> <span class=\"greek\">ῥήματα</span> (v. <span class=\"greek\">ἄρρητος</span> 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 12:4</a>. <span class=\"greek\">ῥ</span>. <span class=\"greek\">ἔκφρικτα</span> Hv 1, 3, 3b. <span class=\"greek\">ῥ</span>. <span class=\"greek\">ἀληθῆ</span> m 11:3; <span class=\"greek\">δεινὰ</span> <span class=\"greek\">ῥ</span>. MPol 8:3. <span class=\"greek\">ῥ</span>. <span class=\"greek\">βλάσφημα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 6:11</a>. <span class=\"greek\">ῥῆμα</span>, <span class=\"greek\">ῥήματα</span> <span class=\"greek\">ἀκούειν</span> B 16:10; Hv 1, 1, 6; 4, 1, 7; 4, 2, 6 al. <span class=\"greek\">τὰ</span> <span class=\"greek\">προειρημένα</span> <span class=\"greek\">ῥ</span>. (v. <span class=\"greek\">προεῖπον</span> 1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 3:2</a>; v. Jd 17; Hm 9:4. <span class=\"greek\">πολὺν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ῥήμασιν</span> <span class=\"greek\">γενέσθαι</span> ser prolixo no falar, ser demasiado loquaz 1 Cl 30:5 (Job 11:3).—<span class=\"greek\">τὸ</span> <span class=\"greek\">ῥ</span>., <span class=\"greek\">τὰ</span> <span class=\"greek\">ῥ</span>. assumem freq. um significado especial a partir do contexto: profecia, predição <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.75\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:75</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:32</a>; 14:72; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.38\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:38</a>; 2:29; 9:45ab; 18:34; 22:61 (v.l. <span class=\"greek\">λόγο</span>); 24:8; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.11.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 11:16</a>; MPol 16:2. Declaração da Escritura 2 Cl 15:4 (cf. Mel., P. 11, 73 <span class=\"greek\">τὰ</span> <span class=\"greek\">ῥ</span>. <span class=\"greek\">τῆ</span> <span class=\"greek\">γραφῆ</span>).—Mandado, mandamento, ordem, instrução <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:5</a>; esp. de Deus (Dt 1:26) 3:2; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.3\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:3</a>; 1 Cl 10:1; <span class=\"greek\">ῥ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">δυνάμεως</span> <span class=\"greek\">αὐτοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:3</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">ἰσχυρὸν</span> <span class=\"greek\">ῥ</span>. a poderosa palavra criadora Hv 1, 3, 4; cf. 3, 3, 5. <span class=\"greek\">διὰ</span> <span class=\"greek\">ῥήματος</span> <span class=\"greek\">Χριστοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 10:17</a>.—Ameaça <span class=\"greek\">λαλεῖν</span> <span class=\"greek\">ῥήματα</span> <span class=\"greek\">κατά</span> <span class=\"greek\">τινος</span> proferir ameaças contra algo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 6:13</a>.—<span class=\"greek\">τὰ</span> <span class=\"greek\">ῥ</span>. discurso, sermão, proclamação <span class=\"greek\">πάντα</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ῥ</span>. <span class=\"greek\">αὐτοῦ</span> tudo o que ele tinha a dizer <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:1</a>. <span class=\"greek\">ἐνωτίσασθε</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ῥήματά</span> <span class=\"greek\">μου</span> prestai atenção ao que proclamo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:14</a>.—10:44; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.20\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:20</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">ῥήματα</span> <span class=\"greek\">αὐτῶν</span> a pregação deles <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 10:18</a> (Ps 18:5).—A respeito de pronunciamentos de ensinamento (cristão) ou de entendimento divino <span class=\"greek\">πῶς</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἐμοῖς</span> <span class=\"greek\">ῥήμασιν</span> <span class=\"greek\">πιστεύσετε</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.47\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:47</a>. Cf. 6:63; 10:21; 12:47f; 14:10; 15:7; 17:8; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:22</a>. <span class=\"greek\">ῥήματα</span> <span class=\"greek\">ζωῆς</span> <span class=\"greek\">αἰωνίου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.68\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:68</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">ῥήματα</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ζωῆς</span> <span class=\"greek\">ταύτης</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:20</a>. <span class=\"greek\">ῥήματα</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">οἷς</span> <span class=\"greek\">σωθήσῃ</span> 11:14. <span class=\"greek\">ῥήματα</span> <span class=\"greek\">ἀληθείας</span> <span class=\"greek\">κ</span>. <span class=\"greek\">σωφροσύνης</span> 26:25. <span class=\"greek\">τὰ</span> <span class=\"greek\">ῥ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> (Sextus 4, 39 <span class=\"greek\">ῥήματα</span> <span class=\"greek\">θεοῦ</span>; Marinus, Vi. Procli 32 <span class=\"greek\">θεῖα</span> <span class=\"greek\">ῥ</span>.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.34\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:34</a>; 8:47. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">παντὶ</span> <span class=\"greek\">ῥήματι</span> <span class=\"greek\">ἐκπορευομένῳ</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">στόματος</span> <span class=\"greek\">θεοῦ</span> (Dt 8:3) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:4</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">ῥήματα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">λεγόμενα</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">παραβολῶν</span> os ensinamentos do Senhor que foram expressos em forma de parábolas Hs 5, 4, 3. <span class=\"greek\">διάσταλμα</span> <span class=\"greek\">ῥήματος</span> o sentido especial do ensinamento B 10:11. Geralmente o sing. reúne todos os ensinamentos divinos como um todo unificado, com algum sentido como evangelho ou confissão: <span class=\"greek\">ἐγγύς</span> <span class=\"greek\">σου</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ῥῆμά</span> <span class=\"greek\">ἐστιν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 10:8</a>a (Dt 30:14); cf. v. 9 v.l. MSuggs, ‘The Word Is Near You’ <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 10:6</a>–10, JKnox Festschr. ’67, 289–312. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.26\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:26</a>. <span class=\"greek\">ἐπότισεν</span> <span class=\"greek\">ῥήματι</span> ele (Paulo) deu a (Artemila) palavras para beber e meditar AcPl Ha 4, 5. <span class=\"greek\">τὸ</span> <span class=\"greek\">ῥῆμα</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">εὐαγγελισθὲν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ὑμᾶς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.25\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:25</a>b. Com gen. objetivo <span class=\"greek\">τὸ</span> <span class=\"greek\">ῥῆμα</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πίστεως</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 10:8</a>b. Com gen. subjetivo <span class=\"greek\">ῥῆμα</span> <span class=\"greek\">θεοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.17\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.5\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6:5</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">ῥ</span>. <span class=\"greek\">κυρίου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.25\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:25</a>a (cf. Is 40:8).—GKittel, D. Wort Gottes im NT: Pastoralblätter für Predigt etc. 80, ’37/38, 345–55.</p><p class=\"entry-text\">② segundo o uso hebraico, um acontecimento acerca do qual se pode falar, coisa, objeto, assunto, acontecimento <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἀδυνατήσει</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">πᾶν</span> <span class=\"greek\">ῥῆμα</span> nada será impossível para Deus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.37\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:37</a> (Gen 18:14). <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">στόματος</span> <span class=\"greek\">δύο</span> <span class=\"greek\">μαρτύρων</span> <span class=\"greek\">σταθῇ</span> <span class=\"greek\">πᾶν</span> <span class=\"greek\">ῥῆμα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.13.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 13:1</a> (ambos Dt 19:15; cf. TestAbr A 13 p. 92, 24 [Stone p. 32]). Cf. o sing. (TestAbr A 15 p. 96, 15 [Stone p. 40]; JosAs 17:1 [CBurchard, A Note on <span class=\"greek\">ῥῆμα</span> in JosAs 17:1f; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:15</a>, 17; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:3</a>: NovT 27, ’85, 281–95]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:15</a> (cf. 1 Km 4:16); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.37\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:37</a>. Pl. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.65\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:65</a>; 2:19, 51; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.32\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:32</a>; 13:42.—ERepo, Der Begriff Rhema im Biblisch-griechischen (Academia Scientia Fennica) I ’52 (LXX); II ’54 (NT e lit. cristã primitiva), mas v. a crítica de GZuntz, L’Antiquité Classique 22, ’53, 106–12.—B. 1262. DELG s.v. <span class=\"greek\">εἴρω</span> (2). M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0315-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ῥησά, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino indeclinável</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Ῥησά</span>, <span class=\"greek\">ὁ</span> indecl. Resá, na genealogia de Jesus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:27</a> (GKuhn, ZNW 22, 1923, 212).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0315-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥῆσις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ῥῆσις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">ἐρῶ</span>; Hom. et al.; pap. [p. ex. Kl.T. 135 p. 47, 8]; LXX, TestSol 1:12 D; SibOr 5, 258; Philo, Just.) palavra, expressão <span class=\"greek\">ἐμῆς</span> <span class=\"greek\">πνοῆς</span> <span class=\"greek\">ῥῆσις</span> (<span class=\"greek\">πνοή</span> 2) 1 Cl 57:3 (Pr 1:23).—DELG s.v. <span class=\"greek\">εἴρω</span> (2).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0315-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥήσσω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ῥήσσω</span></p><p class=\"entry-text\">① forma variante de <span class=\"greek\">ῥήγνυμι</span>, q.v.</p><p class=\"entry-text\">② o épico <span class=\"greek\">ῥήσσω</span> (v. <span class=\"greek\">προσρήσσω</span> e a lit. ali indicada)=át. <span class=\"greek\">ῥάττω</span> fazer cair, lançar ao chão (Artem. 1, 60; Wsd 4:19) <span class=\"greek\">τινά</span> alguém</p><p class=\"entry-text\">ⓐ lit., a respeito do tratamento que um espírito maligno inflige à sua vítima, lançada ao chão em convulsões <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.42\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:42</a> (cf. Eur., Ba. 633 <span class=\"greek\">δώματ</span>’ <span class=\"greek\">ἔρρηξεν</span> <span class=\"greek\">χαμᾶζε</span>)</p><p class=\"entry-text\">ⓑ fig., a respeito do diabo, que procura fazer cair o justo Hm 11:3.—DELG s.v. <span class=\"greek\">ῥήγνυμι</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0315-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥήτωρ, ορος, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ῥήτωρ</span>, <span class=\"greek\">ορος</span>, <span class=\"greek\">ὁ</span> originariamente ‘orador público, orador’ (desde Soph.; Thu. 8, 1, 1 et al.; inscr., pap.; Philo, Vi. Cont. 31; Jos., Ant. 17, 226; 19, 208), depois espec. aquele que fala em tribunal, advogado, procurador (Dio Chrys. 59 [76], 4; POxy 37 I, 4 [49 d.C.]; 237 VII, 25; BGU 969 I, 8; 15 al. em pap.; Preisigke, Fachw. 1915) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 24:1</a>, aqui como advogado da acusação; sobre a forma do discurso de Tértulo v. BWinter, JTS 42, ’91, 505–31.—DELG s.v. <span class=\"greek\">εἴρω</span> (2). M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0315-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥητῶς</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ῥητῶς</span> (adv. de <span class=\"greek\">ῥητός</span> ‘expressamente declarado’) relativo ao que é ou foi declarado como sendo precisamente assim, expressamente, explicitamente (Aristot. 1017b, 1; 3; Stoic. III 219, 45; Polyb. 3, 23, 5; Plut., Brut. 997 [29, 4]; Diog. L. 8, 71; OGI 515, 39; SIG 685, 77 e 83; UPZ 110, 62 [164 a.C.]; POxy 237 VII, 7; Philo, Leg. All. 1, 60 al.; Jos., Ant. 1, 24, C. Ap. 1, 83; Just.) <span class=\"greek\">τὸ</span> <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">ῥητῶς</span> <span class=\"greek\">λέγει</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 4:1</a>.—DELG s.v. <span class=\"greek\">εἴρω</span> (2). M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0315-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥίζα, ης, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ῥίζα</span>, <span class=\"greek\">ης</span>, <span class=\"greek\">ἡ</span> (sobre a formação v. Schwyzer I 352, cf. lat. radix; Hom.+; inscr., pap., LXX; OdeSol 11:16b; TestJud 24:5; Philo; Jos., Ant. 3, 174 al.; Tat. 12, 3f).</p><p class=\"entry-text\">① a parte subterrânea de uma planta, raiz</p><p class=\"entry-text\">ⓐ lit. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:9</a>; Hs 9, 1, 6; 9, 21, 1. <span class=\"greek\">ἐκ</span> <span class=\"greek\">ῥιζῶν</span> até as raízes, de raiz e ramos (Heraclid. Pont., Fgm. 50 W.; Plut., Pomp. 629 [21, 3]; Polyaenus 2, 1, 10; Job 31:12; Aesop, Fab. 70 P.=101 Ch.//71 H-H.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:20</a>. <span class=\"greek\">ῥίζαν</span> <span class=\"greek\">ἔχειν</span> ter raiz(es) (profundas) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:6</a> (Theophr., HP 6, 6, 7 <span class=\"greek\">πολλὴν</span> <span class=\"greek\">ἔχουσα</span> <span class=\"greek\">ῥίζαν</span>; Reader, Polemo p. 372).</p><p class=\"entry-text\">ⓑ em linguagem figurada e em sentido translato (LXX; freq. Philo; SibOr 3, 396): na parábola <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔχειν</span> <span class=\"greek\">ῥίζαν</span> (<span class=\"greek\">ἐν</span> <span class=\"greek\">ἑαυτῷ</span>) não ter raiz firme e, por conseguinte, estar facilmente inclinado a apostatar <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:13</a>.—Na figura paulina da oliveira, sua raiz e seus ramos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:16</a>–18. Sobre <span class=\"greek\">ῥίζας</span> <span class=\"greek\">βάλλειν</span> 1 Cl 39:8 (Job 5:3) v. <span class=\"greek\">βάλλω</span> 3c.—A respeito das origens a partir das quais algo se desenvolve (Socrat., Ep. 14, 2; Herm. Wr. 4, 10): uma família ou nação (Ael. Aristid. 30, 16 K.=10 p. 120 D.; OGI 383, 30f [I a.C.] <span class=\"greek\">ἐμοῦ</span> <span class=\"greek\">γένους</span> <span class=\"greek\">ῥίζα</span>) <span class=\"greek\">ἐκκόπτειν</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">ῥιζῶν</span> extirpar, destruir inteiramente, raiz e ramos B 12:9 (cf. <span class=\"greek\">ἐκ</span> <span class=\"greek\">ῥιζῶν</span> <span class=\"greek\">ἐξαιρεῖν</span> Jos, Ant. 9, 181). <span class=\"greek\">ῥίζα</span> <span class=\"greek\">πικρίας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.15\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:15</a> (<span class=\"greek\">πικρία</span> 1). <span class=\"greek\">ῥ</span>. <span class=\"greek\">πάντων</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">κακῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:10</a> (cf. SibOr 3, 234; Constantin. Manasses 2, 9 H.: <span class=\"greek\">φθόνος</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ῥίζα</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">κακῶν</span>; Himerius, Ecl. 32, 5 W.: <span class=\"greek\">παιδεία</span> <span class=\"greek\">ῥίζα</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀγαθῶν</span>; Straub 31). <span class=\"greek\">τῆς</span> <span class=\"greek\">πίστεως</span> <span class=\"greek\">ῥ</span>. Pol 1:2 (cf. Epicurus em Athen. 12, 67 p. 546f [HUsener, Epicurea 1887 p. 278, 10] <span class=\"greek\">ἀρχὴ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ῥίζα</span> <span class=\"greek\">παντὸς</span> <span class=\"greek\">ἀγαθοῦ</span>; Plut., Mor., 4b <span class=\"greek\">πηγὴ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ῥίζα</span> <span class=\"greek\">καλοκἀγαθίας</span>; Sir 1:6, 20 <span class=\"greek\">ῥ</span>. <span class=\"greek\">σοφίας</span>; Wsd 15:3 <span class=\"greek\">ῥ</span>. <span class=\"greek\">ἀθανασίας</span>).</p><p class=\"entry-text\">② aquilo que cresce de uma raiz, broto, rebento, em nossa lit. em linguagem figurada, descendente (Diod S 26, 16a <span class=\"greek\">μηδὲ</span> <span class=\"greek\">ῥίζαν</span> <span class=\"greek\">ἀπολιπεῖν</span> <span class=\"greek\">συγγενείας</span>=nem um único rebento da família deveria sobreviver; Ps.-Apollod. 2, 1, 4, 2 ’ <span class=\"greek\">Αγήνωρ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">μεγάλης</span> <span class=\"greek\">ῥίζης</span> <span class=\"greek\">ἐγένετο</span> <span class=\"greek\">γενεάρχης</span>=o progenitor da vigorosa linhagem; Sir 40:15; 1 Macc 1:10) a respeito do Messias <span class=\"greek\">ἡ</span> <span class=\"greek\">ῥίζα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἰεσσαί</span> o Rebento de Jessé <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 15:12</a> (Is 11:10); <span class=\"greek\">ἡ</span> <span class=\"greek\">ῥίζα</span> <span class=\"greek\">Δαυίδ</span> (cf. Sir 47:22) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.5.5\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 5:5</a>; cf. 22:16. <span class=\"greek\">ὡς</span> <span class=\"greek\">ῥίζα</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">γῇ</span> <span class=\"greek\">διψώσῃ</span> 1 Cl 16:3 (Is 53:2).</p><p class=\"entry-text\">③ Hs 9, 30, 1f fala das <span class=\"greek\">ῥίζαι</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὄρους</span> (a respeito de uma montanha, colina etc., como seu sopé: Aeschyl., Prom. 365 [pl.]; Polyb. 2, 66, 10; Diod S 20, 41, 3; Plut., Sulla 461 [16, 1]; Jos., Bell. 5, 239).—B. 523. DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0315-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥιζόω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ῥιζόω</span> (<span class=\"greek\">ῥιζα</span>; Hom. et al.; LXX; PsSol 14:4; Philo; Jos., Bell. 4, 471) aor. <span class=\"greek\">ἐρρίζωσα</span> Sir 24:12; perf. 3ª pess. sing. <span class=\"greek\">ἐρρίζωκεν</span> Sir 3:28. Pass.: aor. 3ª pess. pl. <span class=\"greek\">ἐρριζώθησαν</span> Jer 12:2; part. perf. <span class=\"greek\">ἐρριζωμένος</span> (com <span class=\"greek\">ρ</span> duplo; v. Schwyzer I 731f) ‘fazer criar raízes’, sobretudo fig., ‘colocar sobre fundamento firme, fixar firmemente’ (Hom. et al.) pass. estar/ficar firmemente enraizado/fixado (Pla., Ep. 7, 336b <span class=\"greek\">ἐξ</span> <span class=\"greek\">ἀμαθίας</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">κακὰ</span> <span class=\"greek\">ἐρρίζωται</span>; Sext. Emp., Math. 1, 271; Kaibel 1078, 7 a respeito de uma ponte <span class=\"greek\">αἰώνιος</span> <span class=\"greek\">ἐρρίζωται</span>) <span class=\"greek\">ἐρριζωμένοι</span>: <span class=\"greek\">ἐν</span> <span class=\"greek\">ἀγάπῃ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 3:17</a>, <span class=\"greek\">ἐν</span> <span class=\"greek\">αὐτῷ</span> (o Senhor) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:7</a> (Nicander, Ther. 183 <span class=\"greek\">ῥιζοῦσθαι</span> <span class=\"greek\">ἐν</span>=estar firmemente enraizado em; Philosoph. Max. 499, 38 <span class=\"greek\">ῥιζωθέντες</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">θεοῦ</span>).—DELG s.v. <span class=\"greek\">ῥίζα</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0315-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥιπή, ῆς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ῥιπή</span>, <span class=\"greek\">ῆς</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">ῥίπτω</span>; Hom. et al.; TestAbr A 4 p. 80, 34 [Stone p. 8]; Philo, Somn. 2, 125, Aet. M. 20; SibOr 5, 464) prim.: ‘um arremesso, o movimento de impulso ou a força mediante a qual algo é lançado para a frente’. O foco na rapidez súbita torna-se facilmente o componente semântico principal com referência a uma variedade de objetos: movimento rápido, p. ex. dos olhos; o ‘lançar’ de um olhar leva um tempo extremamente curto: <span class=\"greek\">ἐν</span> <span class=\"greek\">ῥιπῇ</span> <span class=\"greek\">ὀφθαλμοῦ</span> num piscar de olhos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.52\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:52</a> (Billerb. II, 156; TestAbr A 4; v. DDaube, The Sudden in the Scriptures ’64, 76–79).—DELG s.v. <span class=\"greek\">ῥίπτω</span>.</p></section></article>"};
